const out = $json.output || {};
const subject = out.subject || '';
const bodyContent = out.body || '';

const html = '<div dir="rtl" style="direction:rtl;font-family:Arial,Helvetica,sans-serif;background:#f4f4f7;padding:24px 0;margin:0;">' +
  '<div style="max-width:600px;margin:0 auto;background:#ffffff;border:1px solid #e0e0e0;border-radius:10px;overflow:hidden;">' +
    '<div style="background:#1a73e8;padding:24px;text-align:center;">' +
      '<div style="display:inline-block;width:52px;height:52px;line-height:52px;background:#ffffff;color:#1a73e8;font-weight:bold;font-size:20px;border-radius:50%;text-align:center;">א.א</div>' +
      '<div style="color:#ffffff;font-size:18px;font-weight:bold;margin-top:10px;">איי.איי אלקטרוניקה</div>' +
    '</div>' +
    '<div style="padding:28px 24px;color:#222222;font-size:15px;line-height:1.8;text-align:right;">' +
      bodyContent +
    '</div>' +
    '<div style="background:#f5f5f7;padding:16px 24px;text-align:center;color:#999999;font-size:12px;border-top:1px solid #eeeeee;">' +
      'איי.איי אלקטרוניקה — חנות אלקטרוניקה ישראלית<br>נשלח אליך כחלק מתהליך יצירת קשר שלנו' +
    '</div>' +
  '</div>' +
'</div>';

return {
  json: {
    subject,
    htmlBody: html
  }
};
